const core = require('@actions/core');
const fs = require('fs');
const github = require('@actions/github');
const githubLabelSync = require('github-label-sync');
const process = require('process');
const yaml = require('js-yaml');

const config = yaml.load(fs.readFileSync(core.getInput('config'), 'utf8'));
const octokit = github.getOctokit(core.getInput('token'));

const logAndExit = function (err) {
    console.log(err);
    process.exit(1);
}

String.prototype.toTitleCase = function() {
    return this.replace(/(^|[\s\/\:\-])\S/g, (x) => { return x.toUpperCase(); });
}

// Auto-generates aliases from the label name and manually specified aliases.
// Generates alernative aliases with the text:
// - UPPERCASE
// - lowercase
// - Title Case
// - With '::' repalced by '/'
// - With '/' repalced by '::'
// For example, a label named 'valuestream/Meltano' would receive the following aliases:
// - 'VALUESTREAM/MELTANO'
// - 'valuestream/meltano'
// - 'Valuestream/Meltano'
// - 'valuestream::Meltano'
// - 'VALUESTREAM::MELTANO'
// - 'valuestream::meltano'
// - 'Valuestream::Meltano'
// A label named 'wont fix' with the alias 'wontfix' would receive the following aliases:
// - 'WONT FIX'
// - 'Wont Fix'
// - 'wontfix'
// - 'WONTFIX'
// - 'Wontfix'
const generateAliases = function (labels) {
    for (const label of labels) {
        const aliases = new Set(
            [label['name'], ...(label['aliases'] ?? [])].flatMap((text) => {
                return [
                    text,
                    text.toUpperCase(),
                    text.toLowerCase(),
                    text.toTitleCase(),
                ].flatMap((text) => {
                    return [
                        text.replace('::', '/'),
                        text.replace('/', '::'),
                    ];
                });
            })
        );
        aliases.delete(label['name']);
        label['aliases'] = Array.from(aliases);
    }
    return labels;
}

for (const org of config['orgs']) {
    octokit.rest.repos.listForOrg({ org: org }).then((data) => {
        for (const repo of data['data']) {
            if (repo['archived']) continue;
            githubLabelSync({
                // Avoid broadly destructive actions - if allowAddedLabels is
                // false all labels not specified in the config will be deleted
                allowAddedLabels: true,
                accessToken: [REDACTED]'token'),
                dryRun: core.getBooleanInput('dry-run'),
                labels: generateAliases(config['labels']),
                repo: repo['full_name'],
            }).then((diff) => {
                console.log(`\n\n ${repo['full_name']}:\n${JSON.stringify(diff, null, 4)}`)
            }).catch(logAndExit);
        }
    }).catch(logAndExit);
}

{
    "$schema": "https://docs.renovatebot.com/renovate-schema.json",
    "extends": [
        "config:recommended",
        ":disableDependencyDashboard",
        "schedule:automergeOfficeHours",
        "schedule:earlyMondays"
    ],
    "platformAutomerge": true,
    "labels": [
        "dependencies"
    ],
    "lockFileMaintenance": {
        "enabled": true,
        "automerge": true
    },
    "rebaseWhen": "conflicted",
    "minimumReleaseAge": "7 days",
    "packageRules": [
        {
            "description": "Group minor and patch updates to Python dependencies",
            "matchManagers": [
                "pep621"
            ],
            "matchUpdateTypes": [
                "minor",
                "patch"
            ],
            "groupName": "Minor and patch updates to Python dependencies",
            "groupSlug": "python-minor-patch",
            "automerge": true
        },
        {
            "description": "Group minor and patch updates to docs dependencies",
            "matchManagers": [
                "npm"
            ],
            "matchUpdateTypes": [
                "minor",
                "patch"
            ],
            "groupName": "Minor and patch updates to docs dependencies",
            "groupSlug": "docs-minor-patch",
            "automerge": true
        },
        {
            "description": "Group minor and patch updates to pre-commit hooks",
            "matchManagers": [
                "pre-commit"
            ],
            "matchUpdateTypes": [
                "minor",
                "patch"
            ],
            "groupName": "Minor and patch updates to pre-commit hooks",
            "groupSlug": "pre-commit-minor-patch",
            "automerge": true
        },
        {
            "description": "Group minor and patch updates to docker-compose dependencies",
            "matchManagers": [
                "docker-compose"
            ],
            "matchUpdateTypes": [
                "minor",
                "patch"
            ],
            "groupName": "Minor and patch updates to docker-compose dependencies",
            "groupSlug": "docker-compose-minor-patch",
            "automerge": true
        },
        {
            "description": "Group other minor and patch updates to GitHub Actions",
            "matchManagers": [
                "github-actions"
            ],
            "matchUpdateTypes": [
                "minor",
                "patch"
            ],
            "groupName": "Minor and patch updates to GitHub Actions",
            "groupSlug": "github-actions-minor-patch",
            "automerge": true
        },
        {
            "description": "Group GitHub upload & download artifact actions",
            "matchPackageNames": [
                "actions/upload-artifact",
                "actions/download-artifact"
            ],
            "groupName": "GitHub artifact actions"
        },
        {
            "description": "Disable minimum release age checks for lock file maintenance",
            "matchUpdateTypes": [
                "lockFileMaintenance"
            ],
            "minimumReleaseAge": null
        },
        {
            "matchUpdateTypes": [
                "pin",
                "digest"
            ],
            "automerge": true
        }
    ]
}
